@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist-mono";

/* Light: Clerk's near-white page (#f7f7f8), white cards and hero, cool graphite text,
   electric violet (#6c47ff) for eyebrows, dots and focus. */
:root {
  --background: oklch(0.976 0.001 286);
  --foreground: oklch(0.188 0.006 286);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.188 0.006 286);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.188 0.006 286);
  --primary: oklch(0.557 0.254 284);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.95 0.003 286);
  --secondary-foreground: oklch(0.188 0.006 286);
  --muted: oklch(0.95 0.003 286);
  --muted-foreground: oklch(0.49 0.024 282);
  --accent: oklch(0.95 0.003 286);
  --accent-foreground: oklch(0.188 0.006 286);
  --destructive: oklch(0.6 0.22 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.188 0.006 286 / 8%);
  --input: oklch(0.887 0.007 286);
  --ring: oklch(0.557 0.254 284);
  --highlight: oklch(0.62 0.13 220);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.62 0.22 286);
  --chart-1: oklch(0.557 0.254 284);
  --chart-2: oklch(0.823 0.135 216);
  --chart-3: oklch(0.9 0.15 107);
  --chart-4: oklch(0.7 0.14 40);
  --chart-5: oklch(0.65 0.17 155);
  --sidebar: oklch(0.985 0.001 286);
  --sidebar-foreground: oklch(0.188 0.006 286);
  --sidebar-primary: oklch(0.557 0.254 284);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.95 0.003 286);
  --sidebar-accent-foreground: oklch(0.188 0.006 286);
  --sidebar-border: oklch(0.188 0.006 286 / 8%);
  --sidebar-ring: oklch(0.557 0.254 284);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 78rem;
  --page-gutter: 1.5rem;
  --section-y: 8rem;
}

/* Dark: the #131316 bands, #212126 cards with a faint top highlight, lilac eyebrows,
   cyan second accent. */
.dark {
  --background: oklch(0.188 0.006 286);
  --foreground: oklch(1 0 0);
  --card: oklch(0.25 0.009 286);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.267 0.009 286);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.688 0.174 288);
  --primary-foreground: oklch(0.188 0.006 286);
  --secondary: oklch(0.283 0.009 286);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.283 0.009 286);
  --muted-foreground: oklch(0.67 0.019 282);
  --accent: oklch(0.311 0.013 279);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.68 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 7%);
  --input: oklch(0.311 0.013 279);
  --ring: oklch(0.688 0.174 288);
  --highlight: oklch(0.853 0.122 214);
  --highlight-foreground: oklch(0.188 0.006 286);
  --glow: oklch(0.6 0.2 286);
  --chart-1: oklch(0.688 0.174 288);
  --chart-2: oklch(0.853 0.122 214);
  --chart-3: oklch(0.92 0.15 107);
  --chart-4: oklch(0.74 0.13 40);
  --chart-5: oklch(0.72 0.16 155);
  --sidebar: oklch(0.21 0.007 286);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.688 0.174 288);
  --sidebar-primary-foreground: oklch(0.188 0.006 286);
  --sidebar-accent: oklch(0.283 0.009 286);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 7%);
  --sidebar-ring: oklch(0.688 0.174 288);
}
